<?php
class ActivityService
{
    private $pdo;
    private $defaults = array(
        'lottery' => array('name'=>'幸运抽奖','description'=>'每日一次抽奖，中奖后获得站内抵扣券。','config'=>array('daily_limit'=>1,'win_weight'=>10)),
        'referral' => array('name'=>'拉人返佣','description'=>'邀请好友完成有效付款后获得佣金，提现由管理员人工审核。','config'=>array('rate_bps'=>1000,'minimum_withdraw_cents'=>5000)),
        'group' => array('name'=>'好友拼单','description'=>'三人成团后享受活动折扣，拼团有效期 24 小时。','config'=>array('target_members'=>3,'discount_percent'=>80,'duration_hours'=>24)),
        'leader' => array('name'=>'团长免单','description'=>'成功邀请 3 名不同用户完成有效付款后，领取一次指定套餐免单权益。','config'=>array('required_referrals'=>3,'reward_plan_id'=>0)),
    );
    public function __construct($pdo){$this->pdo=$pdo;}
    public function defaults($key){return isset($this->defaults[$key])?$this->defaults[$key]:array('name'=>$key,'description'=>'','config'=>array());}
    public function setting($key,$lock=false){
        $sql='SELECT * FROM activity_settings WHERE activity_key=?'.($lock?' FOR UPDATE':'');
        try{$s=$this->pdo->prepare($sql);$s->execute(array($key));$row=$s->fetch();}catch(Exception $e){return null;}
        if($row)return $row;
        $d=$this->defaults($key);$now=date('Y-m-d H:i:s');
        try{$this->pdo->prepare('INSERT INTO activity_settings(activity_key,name,description,status,config_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?)')->execute(array($key,$d['name'],$d['description'],'disabled',json_encode($d['config'],JSON_UNESCAPED_UNICODE),$now,$now));$s=$this->pdo->prepare('SELECT * FROM activity_settings WHERE activity_key=?'.($lock?' FOR UPDATE':''));$s->execute(array($key));return $s->fetch();}catch(Exception $e){return null;}
    }
    public function config($key){$row=$this->setting($key);$base=$this->defaults($key)['config'];$saved=$row&&$row['config_json']?json_decode($row['config_json'],true):array();return array_merge($base,is_array($saved)?$saved:array());}
    public function enabled($key){$row=$this->setting($key);if(!$row||$row['status']!=='enabled')return false;$now=time();return (!$row['start_at']||strtotime($row['start_at'])<=$now)&&(!$row['end_at']||strtotime($row['end_at'])>=$now);}
    public function saveSetting($key,$input,$adminId){$d=$this->defaults($key);$config=array_merge($d['config'],is_array($input['config'])?$input['config']:array());$status=in_array($input['status'],array('enabled','disabled'),true)?$input['status']:'disabled';$name=trim(isset($input['name'])?$input['name']:$d['name']);$description=trim(isset($input['description'])?$input['description']:$d['description']);$start=isset($input['start_at'])&&$input['start_at']!==''?$input['start_at']:null;$end=isset($input['end_at'])&&$input['end_at']!==''?$input['end_at']:null;$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO activity_settings(activity_key,name,description,status,config_json,start_at,end_at,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),status=VALUES(status),config_json=VALUES(config_json),start_at=VALUES(start_at),end_at=VALUES(end_at),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)')->execute(array($key,$name,$description,$status,json_encode($config,JSON_UNESCAPED_UNICODE),$start,$end,$adminId,$adminId,$now,$now));return $this->setting($key);}
    private function code($prefix){return strtoupper($prefix.date('ymdHis').substr(strtoupper(bin2hex(random_bytes(8))),0,8));}
    private function notify($uid,$type,$title,$content){$this->pdo->prepare('INSERT INTO notifications(user_id,type,title,content,created_at) VALUES(?,?,?,?,?)')->execute(array($uid,$type,$title,$content,date('Y-m-d H:i:s')));}
    public function referralCode($userId){$s=$this->pdo->prepare('SELECT referral_code FROM users WHERE id=? AND status="active"');$s->execute(array((int)$userId));$code=(string)$s->fetchColumn();if($code!=='')return $code;$code='R'.strtoupper(substr(bin2hex(random_bytes(10)),0,20));$this->pdo->prepare('UPDATE users SET referral_code=? WHERE id=? AND (referral_code IS NULL OR referral_code="")')->execute(array($code,(int)$userId));$s=$this->pdo->prepare('SELECT referral_code FROM users WHERE id=?');$s->execute(array((int)$userId));return (string)$s->fetchColumn();}
    public function referrerByCode($code){$code=strtoupper(trim($code));if(preg_match('/^R[0-9A-F]{20}$/',$code)){$s=$this->pdo->prepare('SELECT id FROM users WHERE referral_code=? AND status="active"');$s->execute(array($code));$id=(int)$s->fetchColumn();if($id)return $id;}if(!preg_match('/^R[0-9A-Z]+$/',$code))return 0;$legacy=base_convert(substr($code,1),36,10);if(!ctype_digit((string)$legacy))return 0;$s=$this->pdo->prepare('SELECT id FROM users WHERE id=? AND status="active"');$s->execute(array((int)$legacy));return (int)$s->fetchColumn();}
    public function bindReferral($userId,$code){$ref=$this->referrerByCode($code);if(!$ref||$ref===$userId)return false;$s=$this->pdo->prepare('SELECT id FROM referral_relations WHERE user_id=?');$s->execute(array($userId));if($s->fetch())return false;$now=date('Y-m-d H:i:s');try{$this->pdo->prepare('INSERT INTO referral_relations(user_id,referrer_user_id,status,source,created_at,updated_at) VALUES(?,?,"active","register",?,?)')->execute(array($userId,$ref,$now,$now));return true;}catch(Exception $e){return false;}}
    public function lottery($userId){
        if(!$this->enabled('lottery'))throw new RuntimeException('幸运抽奖当前未开启。');$cfg=$this->config('lottery');$today=date('Y-m-d');$this->pdo->beginTransaction();try{$lock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$lock->execute(array($userId));if(!$lock->fetch())throw new RuntimeException('用户不存在。');$a=$this->setting('lottery',true);$s=$this->pdo->prepare('SELECT COUNT(*) FROM lottery_draws WHERE activity_id=? AND user_id=? AND created_at>=? AND created_at<? FOR UPDATE');$s->execute(array($a['id'],$userId,$today.' 00:00:00',date('Y-m-d',strtotime('+1 day')).' 00:00:00'));if((int)$s->fetchColumn()>=$cfg['daily_limit'])throw new RuntimeException('今天的抽奖次数已用完。');$ps=$this->pdo->prepare('SELECT * FROM lottery_prizes WHERE activity_id=? AND status="active" AND weight>0 AND (remaining_quantity<0 OR remaining_quantity>0) ORDER BY sort_order,id FOR UPDATE');$ps->execute(array($a['id']));$prizes=$ps->fetchAll();if(!$prizes)throw new RuntimeException('当前奖池暂无可用奖品，请稍后再试。');$winner=null;$total=0;foreach($prizes as $p)$total+=(int)$p['weight'];$roll=random_int(1,10000);$cursor=0;$winWeight=max(0,min(100,(int)$cfg['win_weight']));if($total>0&&$roll<=$winWeight*100){$pick=random_int(1,$total);foreach($prizes as $p){$cursor+=(int)$p['weight'];if($pick<=$cursor){$winner=$p;break;}}}$drawNo=$this->code('D');$requestKey=(int)$cfg['daily_limit']===1?'lottery:'.$a['id'].':'.$userId.':'.$today:null;$this->pdo->prepare('INSERT INTO lottery_draws(draw_no,request_key,activity_id,user_id,prize_id,status,result_code,result_payload,created_at,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute(array($drawNo,$requestKey,$a['id'],$userId,$winner?$winner['id']:null,$winner?'won':'no_prize',$winner?$winner['prize_code']:'',json_encode($winner?$winner:array('name'=>'谢谢参与'),JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s'),date('Y-m-d H:i:s')));if(!$winner){$this->notify($userId,'lottery','抽奖结果','本次抽奖未中奖，明天还可以继续参与。');$this->pdo->commit();return array('won'=>false,'message'=>'谢谢参与，明天再来试试。');}$coupon=$this->issueCoupon($userId,$a['id'],$winner['name'],(int)$winner['value_cents'],0,(int)$winner['valid_days'],(int)$winner['min_amount_cents']);if((int)$winner['remaining_quantity']>=0){$stock=$this->pdo->prepare('UPDATE lottery_prizes SET remaining_quantity=remaining_quantity-1,updated_at=? WHERE id=? AND status="active" AND remaining_quantity>0');$stock->execute(array(date('Y-m-d H:i:s'),$winner['id']));if($stock->rowCount()!==1)throw new RuntimeException('奖品库存刚刚耗尽，请重新抽奖。');}$this->notify($userId,'lottery','恭喜中奖','你获得了「'.$winner['name'].'」，优惠券 '.$coupon['code'].' 已发放。');$this->pdo->commit();return array('won'=>true,'prize'=>$winner['name'],'coupon'=>$coupon['code']);}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function issueCoupon($userId,$activityId,$name,$amountCents,$percent=0,$days=30,$minCents=0,$planId=0){$now=date('Y-m-d H:i:s');$code=$this->code('CP');$expires=date('Y-m-d H:i:s',strtotime('+'.max(1,(int)$days).' days'));$this->pdo->prepare('INSERT INTO coupons(activity_id,user_id,code,name,coupon_type,amount_cents,discount_percent,max_discount_cents,min_amount_cents,product_plan_id,total_quantity,used_quantity,per_user_limit,status,starts_at,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,1,0,1,"active",?,?,?,?)')->execute(array($activityId,$userId,$code,$name,$percent?'percent':'fixed',$amountCents,$percent,0,$minCents,$planId,$now,$expires,$now,$now));return array('id'=>$this->pdo->lastInsertId(),'code'=>$code);}
    public function userCoupons($userId){try{$s=$this->pdo->prepare('SELECT * FROM coupons WHERE user_id=? ORDER BY id DESC');$s->execute(array($userId));return $s->fetchAll();}catch(Exception $e){return array();}}
    public function prepareCoupon($userId,$code,$planId,$amount){if(!$code)return array('discount'=>0);$s=$this->pdo->prepare('SELECT * FROM coupons WHERE code=? AND user_id=? AND status="active" FOR UPDATE');$s->execute(array(trim($code),$userId));$c=$s->fetch();if(!$c)throw new RuntimeException('优惠券不存在或已失效。');$now=time();if($c['starts_at']&&strtotime($c['starts_at'])>$now||$c['expires_at']&&strtotime($c['expires_at'])<$now)throw new RuntimeException('优惠券已过期或尚未生效。');if((int)$c['min_amount_cents']>$amount)throw new RuntimeException('订单金额未达到优惠券使用门槛。');if(!empty($c['product_plan_id'])&&(int)$c['product_plan_id']!==(int)$planId)throw new RuntimeException('该优惠券不适用于当前方案。');$discount=$c['coupon_type']==='percent'?intdiv($amount*(int)$c['discount_percent'],100):(int)$c['amount_cents'];if((int)$c['max_discount_cents']>0)$discount=min($discount,(int)$c['max_discount_cents']);$discount=min($amount,max(0,$discount));return array('discount'=>$discount,'coupon'=>$c);}
    public function applyPromotion($orderId,$promotion,$code){if(empty($promotion['coupon']))return;$c=$promotion['coupon'];$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE coupons SET status="used",used_quantity=used_quantity+1,used_order_id=?,updated_at=? WHERE id=? AND status="active"')->execute(array($orderId,$now,$c['id']));$this->pdo->prepare('INSERT INTO order_promotions(order_id,promotion_key,promotion_type,promotion_id,promotion_code,coupon_id,discount_amount_cents,idempotency_key,created_at,updated_at) VALUES(?,"coupon","coupon",?,?,?, ?,?,?,?)')->execute(array($orderId,$c['id'],$code,$c['id'],$promotion['discount'],'coupon:'.$orderId,$now,$now));}
    public function settlePaidOrder($orderId){$o=$this->pdo->prepare('SELECT * FROM orders WHERE id=?');$o->execute(array($orderId));$order=$o->fetch();if(!$order||!in_array($order['status'],array('pending_delivery','delivered'),true)||empty($order['paid_at']))return;$s=$this->pdo->prepare('SELECT * FROM referral_relations WHERE user_id=? AND status="active" FOR UPDATE');$s->execute(array($order['user_id']));$rel=$s->fetch();if($rel&&$this->enabled('referral')){$cfg=$this->config('referral');$existing=$this->pdo->prepare('SELECT id FROM referral_commissions WHERE referred_user_id=? AND status IN ("available","approved","paid") ORDER BY id LIMIT 1 FOR UPDATE');$existing->execute(array($order['user_id']));if($existing->fetch()){$this->tryLeaderReward($rel['referrer_user_id']);return;}$key='commission:'.$orderId;$amount=(int)floor($order['total_amount_cents']*(int)$cfg['rate_bps']/10000);if($amount>0){try{$this->pdo->prepare('INSERT INTO referral_commissions(commission_no,idempotency_key,relation_id,referrer_user_id,referred_user_id,order_id,amount_cents,rate_bps,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,"available",?,?)')->execute(array($this->code('CM'),$key,$rel['id'],$rel['referrer_user_id'],$order['user_id'],$orderId,$amount,$cfg['rate_bps'],date('Y-m-d H:i:s'),date('Y-m-d H:i:s')));$this->notify($rel['referrer_user_id'],'referral_commission','邀请返佣到账','好友订单已付款，你获得返佣 ¥'.number_format($amount/100,2).'。');}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;}}}$this->tryLeaderReward($rel?$rel['referrer_user_id']:0);}
    private function tryLeaderReward($userId){if(!$userId||!$this->enabled('leader'))return;$userLock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$userLock->execute(array($userId));if(!$userLock->fetch())return;$cfg=$this->config('leader');$need=max(1,(int)$cfg['required_referrals']);$s=$this->pdo->prepare('SELECT COUNT(DISTINCT referred_user_id) FROM referral_commissions WHERE referrer_user_id=? AND status IN ("available","approved","paid")');$s->execute(array($userId));if((int)$s->fetchColumn()<$need||empty($cfg['reward_plan_id']))return;$a=$this->setting('leader');$s=$this->pdo->prepare('SELECT id FROM leader_rewards WHERE campaign_id=? AND leader_user_id=? FOR UPDATE');$s->execute(array($a['id'],$userId));if($s->fetch())return;$s=$this->pdo->prepare('SELECT pp.price_cents,pp.name FROM product_plans pp WHERE pp.id=? AND pp.status="active"');$s->execute(array((int)$cfg['reward_plan_id']));$plan=$s->fetch();if(!$plan)return;$coupon=$this->issueCoupon($userId,$a['id'],'团长免单券',(int)$plan['price_cents'],0,30,0,(int)$cfg['reward_plan_id']);$this->pdo->prepare('INSERT INTO leader_rewards(campaign_id,leader_user_id,coupon_id,reward_cents,status,awarded_at,created_at,updated_at) VALUES(?,?,?, ?,"awarded",?,?,?)')->execute(array($a['id'],$userId,$coupon['id'],$plan['price_cents'],date('Y-m-d H:i:s'),date('Y-m-d H:i:s'),date('Y-m-d H:i:s')));$this->notify($userId,'leader_reward','团长免单已达成','你已邀请 '.$need.' 名好友完成付款，团长免单券已发放。');}
    public function requestWithdrawal($userId,$amountCents,$channel,$accountName,$accountNo){$cfg=$this->config('referral');$amount=(int)$amountCents;if($amount<(int)$cfg['minimum_withdraw_cents'])throw new InvalidArgumentException('提现金额未达到最低提现金额。');$channel=trim((string)$channel);$accountName=substr(trim((string)$accountName),0,120);$accountNo=substr(trim((string)$accountNo),0,190);if($channel===''||$accountNo==='')throw new InvalidArgumentException('请填写完整的收款信息。');$this->pdo->beginTransaction();try{$lock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$lock->execute(array($userId));if(!$lock->fetch())throw new RuntimeException('用户不存在。');$s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN status IN ("available","approved") THEN amount_cents ELSE 0 END),0)-COALESCE((SELECT SUM(amount_cents) FROM withdrawal_requests WHERE user_id=? AND status IN ("pending","approved","paid")),0) FROM referral_commissions WHERE referrer_user_id=? FOR UPDATE');$s->execute(array($userId,$userId));if((int)$s->fetchColumn()<$amount)throw new RuntimeException('可提现佣金余额不足。');$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO withdrawal_requests(request_no,user_id,amount_cents,net_amount_cents,channel,account_name,account_no,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,"pending",?,?)')->execute(array($this->code('WD'),$userId,$amount,$amount,$channel,$accountName,$accountNo,$now,$now));$id=$this->pdo->lastInsertId();$this->pdo->commit();return $id;}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function processWithdrawal($id,$adminId,$status,$reason){if(!in_array($status,array('approved','rejected','paid'),true))throw new InvalidArgumentException('提现状态无效。');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT * FROM withdrawal_requests WHERE id=? FOR UPDATE');$s->execute(array((int)$id));$w=$s->fetch();if(!$w)throw new RuntimeException('提现申请不存在。');$allowed=($w['status']==='pending'&&in_array($status,array('approved','rejected'),true))||($w['status']==='approved'&&$status==='paid');if(!$allowed)throw new RuntimeException('提现状态不能从 '.$w['status'].' 变更为 '.$status.'。');$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE withdrawal_requests SET status=?,reviewed_by=?,reviewed_at=?,paid_at=IF(?="paid",?,paid_at),reject_reason=?,updated_at=? WHERE id=?')->execute(array($status,$adminId,$now,$status,$status==='paid'?$now:null,substr($reason,0,500),$now,$id));$this->notify($w['user_id'],'withdrawal_'.$status,'提现申请已更新','你的提现申请 '.$w['request_no'].' 状态为：'.$status.'。');$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array($adminId,'process_withdrawal','withdrawal',$id,json_encode(array('status'=>$status,'reason'=>substr($reason,0,500)),JSON_UNESCAPED_UNICODE),$now));$this->pdo->commit();}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function reverseOrder($orderId){$s=$this->pdo->prepare('UPDATE referral_commissions SET status="reversed",updated_at=? WHERE order_id=? AND status IN ("available","approved","paid")');$s->execute(array(date('Y-m-d H:i:s'),$orderId));}
    public function referralSummary($userId){$s=$this->pdo->prepare('SELECT COUNT(*) FROM referral_relations WHERE referrer_user_id=? AND status="active"');$s->execute(array($userId));$invited=(int)$s->fetchColumn();$s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN status IN ("available","approved","paid") THEN amount_cents ELSE 0 END),0) FROM referral_commissions WHERE referrer_user_id=?');$s->execute(array($userId));$earned=(int)$s->fetchColumn();$s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN status IN ("pending","approved","paid") THEN amount_cents ELSE 0 END),0) FROM withdrawal_requests WHERE user_id=?');$s->execute(array($userId));$reserved=(int)$s->fetchColumn();return array('invited'=>$invited,'earned'=>$earned,'available'=>max(0,$earned-$reserved),'code'=>$this->referralCode($userId));}
    public function commissions($userId){$s=$this->pdo->prepare('SELECT c.*,u.email FROM referral_commissions c LEFT JOIN users u ON u.id=c.referred_user_id WHERE c.referrer_user_id=? ORDER BY c.id DESC LIMIT 50');$s->execute(array($userId));return $s->fetchAll();}
    public function withdrawals($userId){$s=$this->pdo->prepare('SELECT * FROM withdrawal_requests WHERE user_id=? ORDER BY id DESC LIMIT 20');$s->execute(array($userId));return $s->fetchAll();}
    public function groupCampaigns(){try{$s=$this->pdo->query('SELECT * FROM group_campaigns WHERE status IN ("active","forming") AND (starts_at IS NULL OR starts_at<=NOW()) AND (expires_at IS NULL OR expires_at>=NOW()) ORDER BY id DESC');return $s->fetchAll();}catch(Exception $e){return array();}}
    public function groupStatus($campaignId,$userId){$s=$this->pdo->prepare('SELECT g.*,m.status member_status FROM group_campaigns g LEFT JOIN group_members m ON m.campaign_id=g.id AND m.user_id=? WHERE g.id=?');$s->execute(array($userId,$campaignId));return $s->fetch();}
    public function allowedGroupPlans($campaignId){$s=$this->pdo->prepare('SELECT pp.*,p.name product_name,p.status product_status FROM group_campaign_plans gp JOIN product_plans pp ON pp.id=gp.product_plan_id JOIN products p ON p.id=pp.product_id WHERE gp.campaign_id=? AND pp.status="active" AND p.status="active" ORDER BY p.sort_order,p.id,pp.sort_order,pp.id');$s->execute(array((int)$campaignId));return $s->fetchAll();}
    public function saveGroupPlans($campaignId,$planIds,$adminId=0){$campaignId=(int)$campaignId;$ids=array();foreach((array)$planIds as $id){$id=(int)$id;if($id>0)$ids[$id]=true;}if(!$ids)throw new InvalidArgumentException('请至少选择一个可拼团套餐方案。');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT id FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array($campaignId));if(!$s->fetch())throw new RuntimeException('拼团活动不存在。');$valid=array();$in=implode(',',array_fill(0,count($ids),'?'));$s=$this->pdo->prepare('SELECT pp.id FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id IN ('.$in.') AND pp.status="active" AND p.status="active"');$s->execute(array_keys($ids));foreach($s as $row)$valid[]=(int)$row['id'];if(count($valid)!==count($ids))throw new InvalidArgumentException('包含不存在或已下架的套餐方案。');$this->pdo->prepare('DELETE FROM group_campaign_plans WHERE campaign_id=?')->execute(array($campaignId));$ins=$this->pdo->prepare('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) VALUES(?,?,?)');$now=date('Y-m-d H:i:s');foreach($valid as $id)$ins->execute(array($campaignId,$id,$now));if($adminId)$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array($adminId,'update_group_plans','group_campaign',$campaignId,json_encode(array('plan_ids'=>$valid),JSON_UNESCAPED_UNICODE),$now));$this->pdo->commit();}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function prepareGroupPromotion($campaignId,$userId,$planId,$amount){$s=$this->pdo->prepare('SELECT g.*,m.id member_id,m.user_id member_user_id,m.role member_role,m.status member_status,p.product_id FROM group_campaigns g JOIN group_members m ON m.campaign_id=g.id AND m.user_id=? JOIN product_plans p ON p.id=? JOIN group_campaign_plans gp ON gp.campaign_id=g.id AND gp.product_plan_id=p.id WHERE g.id=? AND g.status="forming" AND m.status="pending" AND p.status="active" AND (g.expires_at IS NULL OR g.expires_at>=NOW()) FOR UPDATE');$s->execute(array($userId,(int)$planId,(int)$campaignId));$g=$s->fetch();if(!$g)throw new RuntimeException('拼团成员或套餐方案未被活动允许。');$cfg=$this->config('group');$discount=min($amount,max(0,(int)floor($amount*(100-(int)$cfg['discount_percent'])/100)));return array('discount'=>$discount,'group'=>$g,'promotion_code'=>'group:'.$g['id']);}
    public function attachGroupOrder($orderId,$promotion){$g=$promotion['group'];$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO group_orders(campaign_id,order_id,user_id,role,status,amount_cents,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,"pending",?,?,?,?)')->execute(array($g['id'],$orderId,$g['member_user_id'],$g['member_role'],(int)$promotion['discount'],'group:'.$orderId,$now,$now));$this->pdo->prepare('UPDATE group_members SET group_order_id=? WHERE id=? AND status="pending"')->execute(array($this->pdo->lastInsertId(),$g['member_id']));}
    public function settleGroupOrder($orderId){$s=$this->pdo->prepare('SELECT go.*,g.target_members,g.status group_status FROM group_orders go JOIN group_campaigns g ON g.id=go.campaign_id WHERE go.order_id=? FOR UPDATE');$s->execute(array($orderId));$row=$s->fetch();if(!$row||$row['status']!=='pending')return;$s=$this->pdo->prepare('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array($row['campaign_id']));$g=$s->fetch();if(!$g||$g['status']!=='forming')return;$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE group_orders SET status="paid",updated_at=? WHERE id=? AND status="pending"')->execute(array($now,$row['id']));$this->pdo->prepare('UPDATE group_members SET status="paid" WHERE group_order_id=? AND status="pending"')->execute(array($row['id']));$count=(int)$g['current_members']+1;$status=$count>=(int)$g['target_members']?'successful':'forming';$this->pdo->prepare('UPDATE group_campaigns SET current_members=?,status=?,updated_at=? WHERE id=?')->execute(array($count,$status,$now,$g['id']));}
    public function reverseGroupOrder($orderId){$s=$this->pdo->prepare('SELECT * FROM group_orders WHERE order_id=? FOR UPDATE');$s->execute(array($orderId));$row=$s->fetch();if(!$row||!in_array($row['status'],array('pending','paid'),true))return;$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE group_orders SET status="cancelled",updated_at=? WHERE id=?')->execute(array($now,$row['id']));$this->pdo->prepare('UPDATE group_members SET status="cancelled",left_at=? WHERE group_order_id=?')->execute(array($now,$row['id']));if($row['status']==='paid')$this->pdo->prepare('UPDATE group_campaigns SET current_members=GREATEST(current_members-1,0),status=IF(status="successful","forming",status),updated_at=? WHERE id=?')->execute(array($now,$row['campaign_id']));}
    public function createGroup($userId,$planId){if(!$this->enabled('group'))throw new RuntimeException('好友拼单当前未开启。');$cfg=$this->config('group');$allowed=array_map('intval',isset($cfg['plan_ids'])&&is_array($cfg['plan_ids'])?$cfg['plan_ids']:array());if(!in_array((int)$planId,$allowed,true))throw new RuntimeException('所选套餐方案未开放拼团。');$s=$this->pdo->prepare('SELECT pp.id,pp.product_id,pp.name,pp.status product_plan_status,p.name product_name,p.status product_status FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id=? AND pp.status="active" AND p.status="active"');$s->execute(array((int)$planId));$plan=$s->fetch();if(!$plan)throw new RuntimeException('套餐方案不存在或已下架。');$now=date('Y-m-d H:i:s');$expires=date('Y-m-d H:i:s',strtotime('+'.max(1,(int)$cfg['duration_hours']).' hours'));$this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO group_campaigns(campaign_no,creator_user_id,product_id,title,target_members,current_members,member_discount_cents,status,starts_at,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,0,0,"forming",?,?,?,?)')->execute(array($this->code('GP'),$userId,$plan['product_id'],$plan['product_name'].' · 好友拼单',(int)$cfg['target_members'],$now,$expires,$now,$now));$id=$this->pdo->lastInsertId();$campaignPlanIds=array_map('intval',isset($cfg['plan_ids'])&&is_array($cfg['plan_ids'])?$cfg['plan_ids']:array());if(!$campaignPlanIds)throw new RuntimeException('当前没有配置可拼团的套餐方案。');$ins=$this->pdo->prepare('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) VALUES(?,?,?)');foreach($campaignPlanIds as $campaignPlanId)$ins->execute(array($id,$campaignPlanId,$now));$this->pdo->prepare('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?, ?,"leader","pending",?)')->execute(array($id,$userId,$now));$this->pdo->commit();return $id;}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function joinGroup($campaignId,$userId,$planId){$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array((int)$campaignId));$g=$s->fetch();if(!$g||$g['status']!=='forming'||($g['expires_at']&&strtotime($g['expires_at'])<time()))throw new RuntimeException('拼团不存在、已成团或已过期。');$s=$this->pdo->prepare('SELECT 1 FROM group_campaign_plans gp JOIN product_plans pp ON pp.id=gp.product_plan_id JOIN products p ON p.id=pp.product_id WHERE gp.campaign_id=? AND gp.product_plan_id=? AND pp.status="active" AND p.status="active"');$s->execute(array((int)$campaignId,(int)$planId));if(!$s->fetch())throw new RuntimeException('所选套餐方案未被该拼团允许。');$s=$this->pdo->prepare('SELECT id,status FROM group_members WHERE campaign_id=? AND user_id=?');$s->execute(array($campaignId,$userId));$existing=$s->fetch();if($existing){if($existing['status']==='pending'){$this->pdo->commit();return array('status'=>'forming','current_members'=>(int)$g['current_members'],'target_members'=>(int)$g['target_members'],'product_id'=>(int)$g['product_id']);}throw new RuntimeException('你已经加入该拼团。');}$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?, ?,"member","pending",?)')->execute(array($campaignId,$userId,$now));$this->pdo->commit();return array('status'=>'forming','current_members'=>(int)$g['current_members'],'target_members'=>(int)$g['target_members'],'product_id'=>(int)$g['product_id']);}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
}
